"""Weekly timesheet rows built from a list of shifts."""

from typing import List

from hourglass.models import Shift


def _validate(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")


def _totals(shifts: List[Shift]) -> list:
    """Rows of (worker, shift count, minutes)."""
    totals = {}
    for shift in shifts:
        count, spent = totals.get(shift.worker, (0, 0))
        spent += shift.span.minutes
        totals[shift.worker] = (count + 1, spent)
    return [(name, *pair) for name, pair in totals.items()]


def _rank(row: tuple) -> tuple:
    """Most minutes first, then most shifts, then name."""
    return (-row[2], -row[1], row[0])


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest workers first.

    Raises ValueError for no shifts or a blank worker name.
    """
    _validate(shifts)
    rows = sorted(_totals(shifts), key=_rank)
    return [_line(*row) for row in rows]

