# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows


def make_shift(worker, begin, finish):
    return Shift(worker, "mon", Span(begin, finish))


class TimesheetRowsTests(unittest.TestCase):
    def test_totals_and_order(self):
        rows = timesheet_rows([
            make_shift("Cato", 540, 600),
            make_shift("Brisa", 540, 840),
            make_shift("Brisa", 900, 1000)
        ])
        self.assertEqual(rows, [
            "Brisa: 2 shifts, 6.7 hours",
            "Cato: 1 shifts, 1.0 hours"
        ])

    def test_ties_go_to_most_shifts_then_name(self):
        rows = timesheet_rows([
            make_shift("Zane", 0, 120),
            make_shift("Abel", 0, 60),
            make_shift("Abel", 60, 120),
            make_shift("Bree", 0, 120)
        ])
        names = [line.split(":")[0] for line in rows]
        self.assertEqual(names, ["Abel", "Bree", "Zane"])

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([make_shift("  ", 0, 60)])


if __name__ == "__main__":
    unittest.main()
